<script>
const piStore=@json(route('indicators-store')),piUpdate=@json(route('indicators-update','__ID__'));function openIndicator(encoded){const f=document.getElementById('indicatorForm'),d=encoded?JSON.parse(atob(encoded)):{};f.reset();f.action=piStore;indicatorMethod.innerHTML='';['name','indicator_category_id','description','measurement_unit','target_value'].forEach(k=>f.elements[k].value=d[k]||'');f.elements.status.value=d.status===false||Number(d.status)===0?'0':'1';indicatorTitle.textContent=encoded?'Edit Performance Indicator':'Add New Performance Indicator';indicatorSave.textContent=encoded?'Update':'Save';if(encoded){f.action=piUpdate.replace('__ID__',d.id);indicatorMethod.innerHTML='<input type="hidden" name="_method" value="PUT">'}}function showIndicator(encoded){const d=JSON.parse(atob(encoded)),root=document.getElementById('indicatorDetailsModal');['name','category','measurement_unit','target_value','description'].forEach(k=>root.querySelector('[data-pi-detail="'+k+'"]').textContent=d[k]||'—');const active=Number(d.status)===1;root.querySelector('[data-pi-detail="status"]').innerHTML='<span class="pi-status '+(active?'':'inactive')+'">'+(active?'Active':'Inactive')+'</span>'}document.addEventListener('DOMContentLoaded',()=>document.querySelectorAll('.pi-confirm').forEach(f=>f.addEventListener('submit',e=>{if(f.dataset.ok)return;e.preventDefault();Swal.fire({title:f.dataset.title,text:f.dataset.delete?'This action cannot be undone.':'',icon:'warning',showCancelButton:true,confirmButtonText:f.dataset.delete?'Delete':'Yes, continue',confirmButtonColor:f.dataset.delete?'#f1416c':'#00b783'}).then(r=>{if(r.isConfirmed){f.dataset.ok='1';f.submit()}})})));
</script>
